  sq := stat_pt(pts, 'potency', mx); sh := stat_pt(pts, 'haste', mx);
  v_spent := sa + sv + sp + sq + sh;
  v_cp := round(v_x * (1 + (c->>'attack')::numeric * sa))::int;
